interface IRabatt
{
    decimal Anwenden(decimal p);
}
class Schueler : IRabatt
{
    public decimal Anwenden(decimal p)
        => p * 0.8m;
}
class Aktion(decimal minus) : IRabatt
{
    public decimal Anwenden(decimal p)
        => p - minus;
}
// 100 → Schueler → Aktion(5) → 75.0

Rechteck r = new Quadrat();
r.Breite = 5;
r.Hoehe = 4;   // setzt auch Breite!
Console.WriteLine(r.Flaeche);
// 16 statt erwarteter 20

interface IAusgabe
{
    void Schreibe(string text);
}
class NotenDienst(IAusgabe ausgabe)
{
    public void Melde(string n, int note)
    {
        if (note == 5)
            ausgabe.Schreibe(
                $"{n}: Frühwarnung!");
    }
}
// Echt: new NotenDienst(
//         new KonsolenAusgabe());
// Test: new NotenDienst(
//         new FakeAusgabe());

